j2:if.script:
        function openNewFindingSinkCondition(){
			var d = new GlideModalForm('Create new condition', 'promin_finding_def_condition');
			d.setOnloadCallback(populateModalForm);
			d.setCompletionCallback(function(action_verb, sys_id, table, displayValue) {
				g_form.setValue("sink_condition", sys_id);
			});
			d.render();

			function populateModalForm() {
				//Access GlideModal g_form
				var sink_condition_form= window.frames["dialog_frame"].g_form;
				var findingConfigType = g_scratchpad.findingConfigType;
				var findingProcessTable = g_scratchpad.findingProcessTable;
				var findingDefSysId = g_scratchpad.findingDefSysId;
				var newTableName = '';
				sink_condition_form.removeOption("type", "CONTEXT");
				if(findingConfigType == "PROCESS"){
					newTableName = findingProcessTable;
					sink_condition_form.setDisplay('entity', false);
				}
				if(findingConfigType == "PROJECT"){
					sink_condition_form.setMandatory('entity', true);
				} 
				if(newTableName != '') {
					sink_condition_form.setValue("table", newTableName);
					sink_condition_form.setReadOnly("table", true);
				}

				if(findingDefSysId != '') {
					sink_condition_form.setValue("finding_def", findingDefSysId);
					sink_condition_form.setReadOnly("finding_def", true);
				}
			}
        }
